WITH enriched AS (SELECT id, store_id, product_id, NTILE(10) OVER (PARTITION BY MONTH(sale_date) ORDER BY revenue DESC, id) AS revenue_bucket, ROW_NUMBER() OVER (PARTITION BY DATE_TRUNC('month', sale_date), product_id ORDER BY units DESC, id) AS row_seq, CORR(units, revenue) OVER (PARTITION BY product_id) AS corr_units_revenue, NTILE(5) OVER (PARTITION BY product_id ORDER BY revenue, id) AS revenue_bucket_2, LAG(revenue, 1) OVER (PARTITION BY store_id, product_id ORDER BY sale_date, id) AS prev_revenue FROM store_sales) SELECT id, store_id, product_id, revenue_bucket, revenue_bucket_2, prev_revenue FROM enriched ORDER BY revenue_bucket DESC NULLS FIRST
